const e=[{Claim:"Armageddon Expo's cosplay contest is held at each regional Armageddon event in New Zealand. Entries are made in one of four divisions printed in the rules: Junior (children 5 to 13 only, at most five entries per city, parents may help up to 50 percent), Novice (beginners at costume making), Open (all non-professionals; anyone who has studied costume or a costume-related field for more than a year enters Open) and Pairs or Groups (entered into Novice or Open).",SourceType:"Primary - the event's own rules document",Source:"Armageddon Expo (New Zealand) Cosplay Competition Rules",Url:"https://armageddonexpo.com/resources/files/picker/armageddon-cosplay-competition-rules.pdf"},{Claim:"The contest is judged on craft and construction only. Each entrant sends a registration form and a construction diary (PDF), then is interviewed by the judge at the event, photographed, and presented on the Main Stage. The rules print no marks, criteria weights, time limits, ranks or grades, so the template carries a single item scored out of a default 100 and no judging criteria.",SourceType:"Primary - the event's own rules document",Source:"Armageddon Expo (New Zealand) Cosplay Competition Rules",Url:"https://armageddonexpo.com/resources/files/picker/armageddon-cosplay-competition-rules.pdf"},{Claim:"Printed awards at each regional event, given at the discretion of the judge: Best Youth (Junior), Best Solo (Novice), Technical Award, Runner Up Best in Show, Best in Show; every regional Best in Show winner goes to the National Armageddon Cosplay Contest Final at Auckland (Spring) for the Armageddon Cosplay Contest Champion award. Prize money is printed but is subject to change and is not modelled (no rank or points table is printed).",SourceType:"Primary - the event's own rules document",Source:"Armageddon Expo (New Zealand) Cosplay Competition Rules",Url:"https://armageddonexpo.com/resources/files/picker/armageddon-cosplay-competition-rules.pdf"},{Claim:"Scope note: the platform has no field for the 75 percent self-made rule, the 25 percent leeway for bought items, the ban on costumes that already won an award, the military clothing and prop weapon safety rules (2 m and 5 kg limits), the one-entry-per-person rule, the Novice-to-Open promotion rule, the construction diary and interview process, or the national final. These are kept as registration rules and notes, not as structure.",SourceType:"Primary - the event's own rules document",Source:"Armageddon Expo (New Zealand) Cosplay Competition Rules",Url:"https://armageddonexpo.com/resources/files/picker/armageddon-cosplay-competition-rules.pdf"}],t="Built from the Armageddon Expo cosplay rules (10 pages, undated; text read and checked against the PDF). LEFT OUT: prize amounts, the national final and champion award (no rank/points table is printed), the construction-diary and interview process, safety rules and the 75/25 percent rule (platform has no field). HONEST GAPS: no judging criteria, marks, time limits or ranks are printed, so none are shipped. Age bands are a working default: Junior 5-13 is printed; Novice and Open are skill-based divisions with no printed age, so 14-99 is used to keep them apart from Junior, and Novice/Open overlap by design. A pair or group enters the Novice or Open division, so the two team groups mirror them. Junior pairs or groups are not described separately and are not modelled. Edition dates, venues and registration deadlines are on the Armageddon website, not in the rules.",a=[{GroupName:"Junior",AgeFrom:5,AgeTo:13,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/kids.webp"},{GroupName:"Novice",AgeFrom:14,AgeTo:99,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/young-adult.webp"},{GroupName:"Open",AgeFrom:14,AgeTo:99,ParticipantTypeSetting:"Individual",AllowOverlapSetting:"Yes",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/adult.webp"},{GroupName:"Novice Pairs and Groups",AgeFrom:14,AgeTo:99,ParticipantTypeSetting:"Team",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"},{GroupName:"Open Pairs and Groups",AgeFrom:14,AgeTo:99,ParticipantTypeSetting:"Team",AllowOverlapSetting:"Yes",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"}],n=[{CompetitionItem:0,Title:"Cosplay Contest",Category:7,CategoryCategoryName:"On Stage",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/fancy-dress.webp",TimeCalculation:"PerHead"}],o=[{CompetitionItem:0,CompetitionItemTitle:"Cosplay Contest",Group:0,GroupGroupName:"Junior",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/fancy-dress.webp"},{CompetitionItem:0,CompetitionItemTitle:"Cosplay Contest",Group:0,GroupGroupName:"Novice",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/fancy-dress.webp"},{CompetitionItem:0,CompetitionItemTitle:"Cosplay Contest",Group:0,GroupGroupName:"Open",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/fancy-dress.webp"},{CompetitionItem:0,CompetitionItemTitle:"Cosplay Contest",Group:0,GroupGroupName:"Novice Pairs and Groups",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/fancy-dress.webp"},{CompetitionItem:0,CompetitionItemTitle:"Cosplay Contest",Group:0,GroupGroupName:"Open Pairs and Groups",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/fancy-dress.webp"}],i={Evidence:e,MaintenanceNote:t,AgeWiseGroups:a,CompetitionItems:n,CompetitionsAssignedToGroup:o};export{a as AgeWiseGroups,n as CompetitionItems,o as CompetitionsAssignedToGroup,e as Evidence,t as MaintenanceNote,i as default};
